    auto zeroVolume=record.approval;for(auto& directory:zeroVolume.directories)directory.volume=0;Check(i::ValidateApproval(static_cast<std::size_t>(record.operation.snapshot.payloadBytes),zeroVolume)==i::Result::Ok,"zero volume serial is permitted when all physical pairs remain distinct");auto prepaid=record.approval;prepaid.policyEnabled=false;prepaid.beforeRawResidual=prepaid.approvedPeak-prepaid.physicalBytes;Check(i::ValidateApproval(record.operation,prepaid)==i::Result::Ok,"disabled policy permits spending already retained baseline responsibility");
