void ApprovalBeforeBodies(const fs::path& root){for(unsigned mode=0;mode<2;++mode){Fixture fixture(root,(L"intent-before-bodies-"+std::to_wstring(mode)).c_str());const auto head=fixture.Init();c::WritePlan plan;Check(fixture.store.PlanApprovedCommit(head,Bytes(8197,0x6d),plan)==R::Ok,"plan actual approved intent-first fixture");const auto approval=fixture.Approval(plan);const auto before=Files(fixture.paths[3]);auto output=head;Observe fault(fixture.paths[3],mode?Fault::IntentFlush:Fault::IntentPartial);R result;
    {Arm arm(fault);result=fixture.store.ExecuteApproved(plan,approval,output);}
    Check(fault.hits==1&&fault.cleanupHits>=1&&result!=R::Ok&&output.SameVersion(head)&&plan.IsConsumed()&&plan.MayHaveWritten(),"actual intent IO and same-handle cleanup both fail while caller output and write-attempt evidence remain correct");
    const auto failed=Files(fixture.paths[3]);unsigned snapshots=0,commits=0,intents=0;std::size_t intentBytes=0;
    for(const auto& entry:before){const auto found=failed.find(entry.first);Check(found!=failed.end()&&found->second==entry.second,"failed approved intent cannot alter any old metadata byte");}
    for(const auto& entry:failed){if(before.count(entry.first))continue;if(entry.first.rfind(L"snapshots\\",0)==0){++snapshots;Check(entry.second.empty(),"new snapshot remains zero length before verified approved intent");}else if(entry.first.rfind(L"commits\\",0)==0){++commits;Check(entry.second.empty(),"new commit remains zero length before verified approved intent");}else if(entry.first.rfind(L"operations\\",0)==0){++intents;intentBytes=entry.second.size();}else Check(false,"intent failure creates no unaccounted metadata file");}
    Check(snapshots==1&&commits==1&&intents==1&&fault.candidateWrites==0,"both real candidate files exist but receive no WriteFile call before approved intent succeeds");
    Check(mode?intentBytes==1136:(intentBytes>128&&intentBytes<1136),"retained actual intent distinguishes complete flushed envelope from partial body");std::printf("DIAG approval-before-bodies mode=%s snapshot=0 commit=0 candidateWrites=%u intentBytes=%llu cleanupFailures=%u\n",mode?"flush":"partial",fault.candidateWrites,static_cast<unsigned long long>(intentBytes),fault.cleanupHits);
    c::WritePlan recovery;Observe inspect(fixture.paths[3]);{Arm arm(inspect);result=fixture.store.PlanRecovery(recovery);}Check(!inspect.creates&&!inspect.writes&&!inspect.flushes&&Files(fixture.paths[3])==failed,"recovery inspection cannot write, discard, or grant authority to retained failed intent");
    if(!mode){Check(result==R::RecoveryRequired&&!recovery.IsValid()&&!recovery.RecoveryApproval(),"partial approved intent is untrusted and offers no recovery permission");continue;}
    Check(result==R::Ok&&recovery.Recovery()==c::RecoveryAction::Rollback&&recovery.RecoveryTarget().SameVersion(head)&&recovery.RecoveryApproval()&&SameApproval(*recovery.RecoveryApproval(),approval),"complete but failed-flush intent can validate exact original approval for rollback only");const auto logs=Logs(fixture);Check(logs.size()==1&&logs.front().info.spec.key==i::ApprovedKey,"retained full failed-flush log has actual approved key");i::ApprovedRecord decoded;Check(i::DecodeApproved(logs.front().bytes.data(),logs.front().bytes.size(),decoded)==i::Result::Ok&&SameApproval(decoded.approval,approval),"actual retained full intent verifies its checksum and all approval fields");c::RecoveryReport report;
    Check(fixture.store.ExecuteRecovery(recovery,report)==R::Ok&&report.rolledBack&&!report.confirmedPublication,"explicit real rollback removes unwritten candidates without retrying commit");c::Snapshot actual;Check(fixture.store.Read(actual)==R::Ok&&actual.SameVersion(head)&&Files(fixture.paths[3])==before,"successful rollback restores exactly original metadata files and head");
}}
void MissingLayout(const fs::path& root){for(unsigned mode=0;mode<2;++mode){Fixture fixture(root,(L"missing-layout-"+std::to_wstring(mode)).c_str());const auto head=fixture.Init();const auto missing=mode?fixture.paths[3]/L".lock":fixture.paths[8];Check(mode?DeleteFileW(missing.c_str())!=FALSE:RemoveDirectoryW(missing.c_str())!=FALSE,"remove only owned idle prerequisite for no-bootstrap test");const auto before=Files(fixture.root);c::WritePlan plan;Observe watch(fixture.paths[3]);R result;{Arm arm(watch);result=fixture.store.PlanApprovedCommit(head,{6,7},plan);}Check(result!=R::Ok&&!plan.IsValid()&&!fs::exists(missing)&&Files(fixture.root)==before&&!watch.creates&&!watch.writes&&!watch.flushes,"approved planning rejects missing prerequisite without bootstrapping or writing");}}
void Ordinary(const fs::path& root){Fixture fixture(root,L"ordinary");const auto head=fixture.Init();auto output=head;Observe fault(fixture.paths[3],Fault::Partial);R result;{Arm arm(fault);result=fixture.store.Commit(head,Bytes(2053,0x77),output);}Check(fault.hits==1&&result==R::Indeterminate,"interrupt unchanged ordinary commit path");const auto logs=Logs(fixture);Check(logs.size()==1&&logs[0].info.spec.key==i::Key&&logs[0].bytes.size()==752,"ordinary publication keeps unchanged legacy key and wire size");c::WritePlan recovery;Check(fixture.store.PlanRecovery(recovery)==R::Ok&&!recovery.RecoveryApproval(),"ordinary recovery never fabricates budget approval");c::RecoveryReport report;Check(fixture.store.ExecuteRecovery(recovery,report)==R::Ok&&report.rolledBack,"ordinary rollback remains usable");}
