int wmain(int argc,wchar_t**argv){try{if(argc==4&&std::wstring(argv[1])==L"--read-approved"){Hooks hooks;ReadApprovedChild(fs::path(argv[2]),std::stoull(argv[3]));return 0;}Check(argc==3&&std::wstring(argv[1])==L"--store","usage: cache_catalog_approval_tests --store NEW_ABSOLUTE_DIR");const fs::path root(argv[2]);Fresh(root);Hooks hooks;Preflight(root);Interrupted(root);ApprovalBeforeBodies(root);MissingLayout(root);Ordinary(root);std::printf("PASS cache catalog approval checks=%u\n",checks);return 0;}catch(const std::exception& e){active=nullptr;std::fprintf(stderr,"FAIL cache catalog approval checks=%u: %s\n",checks,e.what());return 1;}}
